#include "tscc/CompilationUnit.h"
#include <cstdlib>
#include <iostream>
using namespace tscc;static void fail(const char*m){std::cerr<<m<<'\n';std::exit(1);}static SourceFile source(std::string text){SourceFile s{"flow.ts",std::move(text),{0}};for(std::size_t i=0;i<s.text.size();++i)if(s.text[i]=='\n')s.line_starts.push_back(i+1);return s;}
int main(){CompilationUnit unit(source("function run(x:number):number {\nlet y:number=0;\nif (x && y) { y++; } else { y--; }\nwhile (y < 3) { if (y === 2) return y; y++; }\ntry { if (x) throw x; } catch (e) { y=1; } finally { y++; }\nreturn y;\ny++;\n}\n"));if(!unit.analyze())fail("flow fixture did not check");if(unit.control_flow.functions.size()!=1)fail("per-function graph missing");const auto&g=unit.control_flow.functions.front();if(g.entry>=g.blocks.size()||g.exit>=g.blocks.size()||g.blocks[g.entry].kind!=BasicBlockKind::Entry||g.blocks[g.exit].kind!=BasicBlockKind::Exit)fail("entry/exit identity missing");bool branch=false,loop=false,short_circuit=false,ret=false,thrown=false,catch_block=false,finally_block=false,back=false,exception=false,finally_edge=false,join=false,unreachable=false;for(const auto&b:g.blocks){if(b.id>=g.blocks.size())fail("unstable block identity");branch|=b.kind==BasicBlockKind::Branch;loop|=b.kind==BasicBlockKind::Loop;short_circuit|=b.kind==BasicBlockKind::ShortCircuit;ret|=b.kind==BasicBlockKind::Return;thrown|=b.kind==BasicBlockKind::Throw;catch_block|=b.kind==BasicBlockKind::Catch;finally_block|=b.kind==BasicBlockKind::Finally;join|=b.predecessors.size()>1;unreachable|=!b.reachable;}for(const auto&e:g.edges){if(e.from>=g.blocks.size()||e.to>=g.blocks.size())fail("invalid edge identity");back|=e.kind==ControlFlowEdgeKind::BackEdge;exception|=e.kind==ControlFlowEdgeKind::Exception;finally_edge|=e.kind==ControlFlowEdgeKind::Finally;}if(!branch||!loop||!short_circuit||!ret||!thrown||!catch_block||!finally_block||!back||!exception||!finally_edge||!join||!unreachable)fail("control-flow topology incomplete");const auto again=build_control_flow(unit.tokens,unit.semantic,unit.expressions);if(again.functions.size()!=1||again.functions[0].blocks.size()!=g.blocks.size()||again.functions[0].edges.size()!=g.edges.size())fail("graph construction is not deterministic");for(std::size_t i=0;i<g.blocks.size();++i)if(again.functions[0].blocks[i].kind!=g.blocks[i].kind||again.functions[0].blocks[i].begin_token!=g.blocks[i].begin_token)fail("stable graph identity changed");std::cout<<"control-flow graph foundation passed\n";}
